function bit [NUM_OF_CLIENTS-1:0] expected_next_grant (input [NUM_OF_CLIENTS-1:0] current_grant, input [NUM_OF_CLIENTS-1:0] tb_req, input integer num_clients);
    integer current_index;
    integer i;
    for (i=0; i<num_clients; i++) begin
        if (current_grant[i]) current_index = i;
    end
    bit [NUM_OF_CLIENTS-1:0] mask = 0;
    for (i = current_index+1; i < num_clients; i++) begin
        if (tb_req[i]) begin
            mask = (1 << i);
            break;
        end
    end
    if (mask == 0) begin
        for (i = 0; i <= current_index; i++) begin
            if (tb_req[i]) begin
                mask = (1 << i);
                break;
            end
        end
    end
    return mask;
endfunction

