// This property checks that when the grant is updated (hold is low), the grant follows the Round Robin order by granting the next requesting client in the circular order.
asrt_round_robin: assert property (@(posedge clk) disable iff (tb_reset)
    if (!hold) begin
        // Get the index of the last grant (previous grant or start from 0 if none)
        int last_gnt_index;
        if (last_gnt == 0) begin
            last_gnt_index = 0;
        end else begin
            last_gnt_index = $clog2(last_gnt);
        end

        // Calculate the next index in circular order
        int next_index = (last_gnt_index + 1) % NUM_OF_CLIENTS;

        // Check if the next client is requesting; if not, skip to the next requesting one (simplified for immediate next)
        // This is a simplified check that only verifies the next immediate client in the order
        // For a complete solution, a helper function or iterative check would be required
        if (tb_req[next_index]) begin
            tb_gnt == (1 << next_index);
        end
    end
);
